USING DUAL ON (T.MSG_ID = 'LBL00086' AND T.LANG_CD = 'CN')
WHEN MATCHED THEN UPDATE SET T.MSG_NM = 'Year', T.MSG_DESC = NULL, T.MSG_TP_CD = 'LBL', T.USE_YN = 'Y', T.CREATED_BY = 'SYSTEM', T.CREATION_DATE = TO_DATE('20260213155329','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'SYSTEM', T.LAST_UPDATE_DATE = TO_DATE('20260213155329','YYYYMMDDHH24MISS')
