VALUES ('LBL00086', 'CN', 'Year', NULL, 'LBL', 'Y', 'SYSTEM', TO_DATE('20260213155329','YYYYMMDDHH24MISS'), 'SYSTEM', TO_DATE('20260213155329','YYYYMMDDHH24MISS'));

